def longest_consecutive(root: Optional[TreeNode]) -> int:
    best = 0
    inc = {}            # id(node) -> longest increasing downward chain starting at node
    dec = {}            # id(node) -> longest decreasing downward chain starting at node
    stack = [(root, False)]
    while stack:
        node, done = stack.pop()
        if node is None:
            continue
        if not done:
            stack.append((node, True))             # revisit after the children
            stack.append((node.left, False))
            stack.append((node.right, False))
            continue
        up, down = 1, 1
        for child in (node.left, node.right):
            if child is None:
                continue
            if child.val == node.val + 1:
                up = max(up, inc[id(child)] + 1)
            elif child.val == node.val - 1:
                down = max(down, dec[id(child)] + 1)
        inc[id(node)] = up
        dec[id(node)] = down
        best = max(best, up + down - 1)            # node is the top of the path
    return best

def num_dup_digits_at_most_n(n: int) -> int:
    digits = [int(c) for c in str(n)]
    L = len(digits)

    def falling(start: int, count: int) -> int:
        # start * (start - 1) * ... for `count` factors
        result = 1
        for i in range(count):
            result *= start - i
        return result

    distinct = 0
    for length in range(1, L):                   # shorter numbers
        distinct += 9 * falling(9, length - 1)

    used = set()
    for i, d in enumerate(digits):
        low = 1 if i == 0 else 0                 # no leading zero
        for x in range(low, d):
            if x not in used:
                distinct += falling(9 - i, L - i - 1)
        if d in used:
            break                                # n's prefix already repeats a digit
        used.add(d)
    else:
        distinct += 1                            # n itself has distinct digits
    return n - distinct

def max_length(ribbons: List[int], k: int) -> int:
    lo, hi = 1, max(ribbons)
    best = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        pieces = sum(r // mid for r in ribbons)   # pieces of length mid
        if pieces >= k:
            best = mid                            # feasible: try longer
            lo = mid + 1
        else:
            hi = mid - 1                          # too long
    return best

