def latest_time_catch_the_bus(buses: List[int], passengers: List[int], capacity: int) -> int:
    buses = sorted(buses)
    passengers = sorted(passengers)
    taken = set(passengers)
    j = 0                                   # next passenger who has not boarded
    boarded = 0
    for depart in buses:
        boarded = 0
        while j < len(passengers) and passengers[j] <= depart and boarded < capacity:
            j += 1
            boarded += 1
    if boarded < capacity:
        candidate = buses[-1]               # a seat is free on the last bus
    else:
        candidate = passengers[j - 1]       # must arrive before the last person who boarded
    while candidate in taken:
        candidate -= 1                      # arrival times must not collide
    return candidate

def maximum_length(s: str) -> int:
    occurrences = defaultdict(int)          # (letter, length) -> number of starting positions
