def count_sequences(nums: List[int], k: int) -> int:
    EXP = {1: (0, 0, 0), 2: (1, 0, 0), 3: (0, 1, 0), 4: (2, 0, 0), 5: (0, 0, 1), 6: (1, 1, 0)}

    # exponents of 2, 3, 5 in k; any other prime factor makes k unreachable
    target = []
    rest = k
    for p in (2, 3, 5):
        e = 0
        while rest % p == 0:
            rest //= p
            e += 1
        target.append(e)
    if rest != 1:
        return 0
    target = tuple(target)

    states = {(0, 0, 0): 1}                     # exponent triple -> number of sequences
    for x in nums:
        dx = EXP[x]
        nxt = defaultdict(int)
        for (a, b, c), ways in states.items():
            nxt[(a, b, c)] += ways                                   # leave unchanged
            nxt[(a + dx[0], b + dx[1], c + dx[2])] += ways           # multiply
            nxt[(a - dx[0], b - dx[1], c - dx[2])] += ways           # divide
        states = nxt
    return states.get(target, 0)

def min_integer(num: str, k: int) -> str:
    n = len(num)
    # queue of original indices for each digit value
    pos = [deque() for _ in range(10)]
    for i, ch in enumerate(num):
        pos[ord(ch) - 48].append(i)

    tree = [0] * (n + 1)                 # Fenwick tree over removed indices

    def mark_removed(i: int) -> None:
        i += 1
        while i <= n:
            tree[i] += 1
            i += i & -i

    def removed_before(i: int) -> int:   # removed indices strictly less than i
        s = 0
        while i > 0:
            s += tree[i]
            i -= i & -i
        return s

    taken = [False] * n
    out = []
    for _ in range(n):
        if k == 0:
            break
        for d in range(10):
            if not pos[d]:
                continue
            i = pos[d][0]
            cost = i - removed_before(i)
            if cost <= k:
                k -= cost
                out.append(chr(48 + d))
                pos[d].popleft()
                mark_removed(i)
                taken[i] = True
                break
    # out of moves: the untouched digits keep their relative order
    for i in range(n):
        if not taken[i]:
            out.append(num[i])
    return "".join(out)

def count_subsets(parent: List[int], nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    n = len(nums)

    def convolve(a: List[int], b: List[int]) -> List[int]:
        """Cyclic convolution modulo k: residues add."""
        out = [0] * k
        for i, ai in enumerate(a):
            if ai:
                for j, bj in enumerate(b):
                    if bj:
                        idx = i + j
                        if idx >= k:
                            idx -= k
                        out[idx] = (out[idx] + ai * bj) % MOD
        return out

    skip = [None] * n   # node left out
    take = [None] * n   # node selected
    for v in range(n):
        s = [0] * k
        s[0] = 1
        t = [0] * k
        t[nums[v] % k] += 1
        skip[v], take[v] = s, t

    # children always have larger indices, so this order finishes a subtree before merging it
    for v in range(n - 1, 0, -1):
        p = parent[v]
        either = [(x + y) % MOD for x, y in zip(skip[v], take[v])]
        skip[p] = convolve(skip[p], either)
        take[p] = convolve(take[p], skip[v])

    return (skip[0][0] + take[0][0] - 1) % MOD

