def selling_wood(m: int, n: int, prices: List[List[int]]) -> int:
    price = [[0] * (n + 1) for _ in range(m + 1)]
    for h, w, p in prices:
        price[h][w] = p

    dp = [[0] * (n + 1) for _ in range(m + 1)]   # dp[h][w]: best revenue for an h x w piece
    for h in range(1, m + 1):
        row = dp[h]
        for w in range(1, n + 1):
            best = price[h][w]                   # sell the piece whole
            for a in range(1, h // 2 + 1):       # horizontal cut (mirror cuts are equivalent)
                v = dp[a][w] + dp[h - a][w]
                if v > best:
                    best = v
            for b in range(1, w // 2 + 1):       # vertical cut
                v = row[b] + row[w - b]
                if v > best:
                    best = v
            row[w] = best
    return dp[m][n]

