class Promise:
    """A small Promise: Promise(executor) where executor(resolve, reject);
    .then(on_fulfilled=None, on_rejected=None) returns a new Promise;
    .catch(on_rejected); Promise.resolve(value); Promise.reject(reason)."""

    def __init__(self, executor):
        self.state = "pending"      # "pending" | "fulfilled" | "rejected"
        self.value = None
        self._callbacks = []
        try:
            executor(self._resolve, self._reject)
        except Exception as e:      # an executor that throws rejects
            self._reject(e)

    def _settle(self, state, value):
        if self.state != "pending":
            return
        self.state, self.value = state, value
        callbacks, self._callbacks = self._callbacks, []
        for cb in callbacks:
            cb()

    def _resolve(self, value):
        if isinstance(value, Promise):
            value.then(self._resolve, self._reject)
        else:
            self._settle("fulfilled", value)

    def _reject(self, reason):
        self._settle("rejected", reason)

    def then(self, on_fulfilled=None, on_rejected=None):
        def executor(resolve, reject):
            def run():
                handler = on_fulfilled if self.state == "fulfilled" else on_rejected
                if handler is None:
                    (resolve if self.state == "fulfilled" else reject)(self.value)
                    return
                try:
                    resolve(handler(self.value))
                except Exception as e:
                    reject(e)
            if self.state == "pending":
                self._callbacks.append(run)
            else:
                run()
        return Promise(executor)

    def catch(self, on_rejected):
        return self.then(None, on_rejected)

    @staticmethod
    def resolve(value):
        return Promise(lambda res, rej: res(value))

    @staticmethod
    def reject(reason):
        return Promise(lambda res, rej: rej(reason))

