def result_array(nums: List[int], k: int, queries: List[List[int]]) -> List[int]:
    n = len(nums)
    size = 1
    while size < n:
        size *= 2
    IDENT = ([0] * k, 1)                    # empty segment: no prefixes, product 1

    def leaf(v: int):
        cnt = [0] * k
        cnt[v % k] = 1
        return (cnt, v % k)

    def merge(left, right):
        lcnt, lprod = left
        rcnt, rprod = right
        cnt = lcnt[:]
        for r in range(k):
            if rcnt[r]:
                cnt[(lprod * r) % k] += rcnt[r]
        return (cnt, (lprod * rprod) % k)

    tree = [IDENT] * (2 * size)
    for i, v in enumerate(nums):
        tree[size + i] = leaf(v)
    for i in range(size - 1, 0, -1):
        tree[i] = merge(tree[2 * i], tree[2 * i + 1])

    def update(i: int, v: int) -> None:
        i += size
        tree[i] = leaf(v)
        i //= 2
        while i:
            tree[i] = merge(tree[2 * i], tree[2 * i + 1])
            i //= 2

    def query(lo: int, hi: int):             # summary of nums[lo..hi)
        left, right = IDENT, IDENT
        lo += size
        hi += size
        while lo < hi:
            if lo & 1:
                left = merge(left, tree[lo])
                lo += 1
            if hi & 1:
                hi -= 1
                right = merge(tree[hi], right)
            lo //= 2
            hi //= 2
        return merge(left, right)

    out = []
    for index, value, start, x in queries:
        update(index, value)
        out.append(query(start, n)[0][x])
    return out

