def get_max_grid_happiness(m: int, n: int, introverts_count: int, extroverts_count: int) -> int:
    if n > m:
        m, n = n, m                      # window spans the shorter side
    total = m * n
    top_place = 3 ** (n - 1)             # digit of the cell directly above
    window = 3 ** n
    BASE = (0, 120, 40)                  # base happiness per kind
    EFFECT = (0, -30, 20)                # what a kind does to each neighbour pair

    @lru_cache(maxsize=None)
    def best(pos: int, intro: int, extro: int, profile: int) -> int:
        if pos == total or (intro == 0 and extro == 0):
            return 0
        col = pos % n
        up = profile // top_place                 # kind above (0 if empty or first row)
        left = profile % 3 if col > 0 else 0      # kind to the left
        shifted = (profile * 3) % window
        result = best(pos + 1, intro, extro, shifted)     # leave the cell empty
        for kind, left_i, left_e in ((1, intro - 1, extro), (2, intro, extro - 1)):
            if left_i < 0 or left_e < 0:
                continue
            gain = BASE[kind]
            for nb in (up, left):
                if nb:
                    gain += EFFECT[kind] + EFFECT[nb]
            result = max(result, gain + best(pos + 1, left_i, left_e, shifted + kind))
        return result

    return best(0, introverts_count, extroverts_count, 0)

def min_total_time(forward: list[int], backward: list[int], queries: list[int]) -> int:
    n = len(forward)
    pf = [0] * (n + 1)        # pf[i] = forward[0] + ... + forward[i - 1]
    pb = [0] * (n + 1)        # pb[i] = backward[0] + ... + backward[i - 1]
