        if a >= b:
            return pb[a + 1] - pb[b + 1]
        return total_b - (pb[b + 1] - pb[a + 1])

    cur = 0
    total = 0
    for q in queries:
        total += min(forward_cost(cur, q), backward_cost(cur, q))
        cur = q
    return total

