def shortest_to_char(s: str, c: str) -> list[int]:
    n = len(s)
    answer = [n] * n
    # left to right: distance to the previous occurrence
    prev = -n
    for i, ch in enumerate(s):
        if ch == c:
            prev = i
        answer[i] = i - prev
    # right to left: distance to the next occurrence
    nxt = 2 * n
    for i in range(n - 1, -1, -1):
        if s[i] == c:
            nxt = i
        if nxt - i < answer[i]:
            answer[i] = nxt - i
    return answer

