def max_active_sections(s: str) -> int:
    ones = s.count("1")
    zero_runs = []
    i, n = 0, len(s)
    while i < n:
        if s[i] == "0":
            j = i
            while j < n and s[j] == "0":
                j += 1
            zero_runs.append(j - i)
            i = j
        else:
            i += 1
    gain = 0
    for a, b in zip(zero_runs, zero_runs[1:]):
        gain = max(gain, a + b)      # two neighbouring zero runs merge and turn active
    return ones + gain

