def construct_maximum_binary_tree(nums: list[int]) -> Optional[TreeNode]:
    stack = []                      # nodes on the right spine, values decreasing
    for v in nums:
        node = TreeNode(v)
        last = None
        while stack and stack[-1].val < v:
            last = stack.pop()      # smaller nodes go into the left subtree
        node.left = last
        if stack:
            stack[-1].right = node  # nearest larger value to the left is the parent
        stack.append(node)
    return stack[0]

def minimum_cost(s: str) -> int:
    n = len(s)
    cost = 0
    for i in range(1, n):
        if s[i] != s[i - 1]:
            # remove the boundary with the cheaper of prefix [0..i-1] or suffix [i..n-1]
            cost += min(i, n - i)
    return cost

