def max_score_words(words: list[str], letters: list[str], score: list[int]) -> int:
    avail = [0] * 26
    for ch in letters:
        avail[ord(ch) - 97] += 1
    info = []                                   # (letter counts as pairs, word value)
    for w in words:
        cnt = Counter(ord(ch) - 97 for ch in w)
        pairs = list(cnt.items())
        info.append((pairs, sum(score[c] * k for c, k in pairs)))
    best = 0

    def dfs(i: int, cur: int) -> None:
        nonlocal best
        if i == len(info):
            best = max(best, cur)
            return
        dfs(i + 1, cur)                         # skip word i
        pairs, value = info[i]
        if all(avail[c] >= k for c, k in pairs):
            for c, k in pairs:
                avail[c] -= k
            dfs(i + 1, cur + value)             # take word i
            for c, k in pairs:
                avail[c] += k

    dfs(0, 0)
    return best

def mice_and_cheese(reward1: list[int], reward2: list[int], k: int) -> int:
    total = sum(reward2)                 # second mouse eats everything
    diffs = [a - b for a, b in zip(reward1, reward2)]
    diffs.sort(reverse=True)
    # hand the first mouse the k pieces with the largest gain
    return total + sum(diffs[:k])

