def stone_game_iii(stone_value: list[int]) -> str:
    n = len(stone_value)
    # dp[i] = best lead for the player to move with stones i..n-1 remaining
    nxt = [0, 0, 0]       # dp[i+1], dp[i+2], dp[i+3]
    best = 0
    for i in range(n - 1, -1, -1):
        best = float("-inf")
        taken = 0
        for t in range(3):
            if i + t >= n:
                break
            taken += stone_value[i + t]
            best = max(best, taken - nxt[t])
        nxt = [best, nxt[0], nxt[1]]
    if best > 0:
        return "Alice"
    if best < 0:
        return "Bob"
    return "Tie"

