def prime_palindrome(n: int) -> int:
    def is_prime(x: int) -> bool:
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        d = 3
        while d * d <= x:
            if x % d == 0:
                return False
            d += 2
        return True

    if 8 <= n <= 11:
        return 11                        # the only even length prime palindrome
    for length in range(1, 6):           # odd lengths 1, 3, 5, 7, 9
        for half in range(10 ** (length - 1), 10 ** length):
            s = str(half)
            p = int(s + s[-2::-1])       # mirror without repeating the middle digit
            if p >= n and is_prime(p):
                return p
    return -1

