def check_valid_cuts(n: int, rectangles: list[list[int]]) -> bool:
    def enough_groups(intervals: list[tuple[int, int]]) -> bool:
        intervals.sort()
        groups = 0
        furthest = -1
        for start, end in intervals:
            if start >= furthest:        # no overlap with the current group: a cut fits here
                groups += 1
                if groups >= 3:
                    return True
            if end > furthest:
                furthest = end
        return False

    xs = [(r[0], r[2]) for r in rectangles]
    ys = [(r[1], r[3]) for r in rectangles]
    return enough_groups(xs) or enough_groups(ys)

def min_falling_path_sum(grid: list[list[int]]) -> int:
    best1 = best2 = 0        # smallest and second smallest path sums of the previous row
    best_col = -1            # column of best1
    for row in grid:
        new1 = new2 = float("inf")
        new_col = -1
        for j, v in enumerate(row):
            cur = v + (best2 if j == best_col else best1)
            if cur < new1:
                new2, new1, new_col = new1, cur, j
            elif cur < new2:
                new2 = cur
        best1, best2, best_col = new1, new2, new_col
    return best1

