            return False
        d += 1
    return True

def highest_peak(is_water: list[list[int]]) -> list[list[int]]:
    m, n = len(is_water), len(is_water[0])
    height = [[-1] * n for _ in range(m)]
    queue = deque()
    for i in range(m):
        for j in range(n):
            if is_water[i][j] == 1:
                height[i][j] = 0
                queue.append((i, j))
    # multi source BFS: each land cell gets its distance to the nearest water
    while queue:
        i, j = queue.popleft()
        h = height[i][j] + 1
        for x, y in ((i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)):
            if 0 <= x < m and 0 <= y < n and height[x][y] == -1:
                height[x][y] = h
                queue.append((x, y))
    return height
